import { useState, useContext } from "react";
import { AuthContext } from "../context/AuthContext";
import "../styles/auth.css";

function Login() {
  const { login } = useContext(AuthContext);

  const [role, setRole] = useState(null);
  const [email, setEmail] = useState("");
  const [pass, setPass] = useState("");
  const [pin, setPin] = useState("");
  const [show, setShow] = useState(false);
  const [error, setError] = useState("");

  /* ⭐ ROLE SELECTION PAGE */
  if (!role) {
    const handleMove = (e, el) => {
      const rect = el.getBoundingClientRect();
      el.style.setProperty("--x", `${e.clientX - rect.left}px`);
      el.style.setProperty("--y", `${e.clientY - rect.top}px`);
    };

    return (
      <div className="split">
        <div
          className="left"
          onMouseMove={(e) => handleMove(e, e.currentTarget)}
          onClick={() => setRole("citizen")}
        >
          <div className="role-card">
            <div className="icon">🏠</div>
            <h1>Citizen</h1>
            <p>Report civic issues easily</p>
          </div>
        </div>

        <div
          className="right"
          onMouseMove={(e) => handleMove(e, e.currentTarget)}
          onClick={() => setRole("admin")}
        >
          <div className="role-card">
            <div className="icon">🏛</div>
            <h1>Authority</h1>
            <p>Manage complaints efficiently</p>
          </div>
        </div>
      </div>
    );
  }

  /* ⭐ LOGIN VALIDATION */
  const handleLogin = () => {
    if (role === "admin") {
      if (
        pin === "1234" &&
        email === "official@gmail.com" &&
        pass === "official@1234"
      ) {
        login(role);
      } else {
        setError("Invalid authority credentials");
      }
    } else {
      if (email && pass) login(role);
      else setError("Enter credentials");
    }
  };

  /* ⭐ LOGIN PAGE */
  return (
    <div className={`auth ${role}`}>
      <div className="auth-card">
        <h2>{role === "citizen" ? "Citizen Login" : "Authority Login"}</h2>

        <div className="social">
          <div>G</div>
          <div>F</div>
          <div></div>
        </div>

        {/* ⭐ AUTHORITY PIN */}
        {role === "admin" && (
          <input
            placeholder="Official Authority PIN"
            value={pin}
            onChange={(e) => setPin(e.target.value)}
          />
        )}

        <input
          placeholder="Email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
        />

        <input
          type={show ? "text" : "password"}
          placeholder="Password"
          value={pass}
          onChange={(e) => setPass(e.target.value)}
        />

        <p onClick={() => setShow(!show)}>
          {show ? "Hide Password" : "Show Password"}
        </p>

        {error && <p style={{ color: "red" }}>{error}</p>}

        <button onClick={handleLogin}>Login</button>

        <p style={{ cursor: "pointer" }} onClick={() => setRole(null)}>
          ← Change Role
        </p>
      </div>
    </div>
  );
}

export default Login;
